import {
  type Menubar as MenubarController,
  type MenubarItemInput,
  type MenubarOptions,
  createMenubar,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createContext, createEffect, merge, onSettled, useContext } from "solid-js";

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

export interface MenubarProps extends MenubarOptions, Renderable<PartProps, void> {
  /** The bar, declared once: the labels are the primitive's typeahead, and the rows come from here. */
  readonly items: ReadonlyArray<string | MenubarItemInput>;
  /** The primitive, once: a scenario fixture needs it; a page rarely does. */
  readonly onReady?: (menubar: MenubarController) => void;
  readonly class?: string;
  /** One `Menubar.Menu` per item, by default; a bar of your own says otherwise. */
  readonly children?: JSX.Element;
}

export interface MenubarMenuProps extends Renderable<PartProps, void> {
  /** The index in the bar's `items` this top-level item is. */
  readonly index: number;
  readonly class?: string;
  /** A `Menubar.Trigger` and, when the item owns one, a `Menubar.Content`. */
  readonly children?: JSX.Element;
}

export type MenubarTriggerPartProps = PartProps;

export interface MenubarTriggerProps extends Renderable<MenubarTriggerPartProps, void> {
  readonly class?: string;
  /** The declared label by default. */
  readonly children?: JSX.Element;
}

export interface MenubarContentProps extends Renderable<PartProps, void> {
  readonly class?: string;
  /** Rows of your own; without children the declared menu items are the rows, in order. */
  readonly children?: JSX.Element;
}

/** What a row's `render` sees: the tab stop the primitive announces, and the declared disabled state. */
export interface MenubarItemState {
  readonly highlighted: () => boolean;
  readonly disabled: () => boolean;
}

export interface MenubarItemProps extends Renderable<PartProps, MenubarItemState> {
  /** The index in the open menu's items this row is. */
  readonly index: number;
  readonly class?: string;
  /** The row's content; the declared label by default. */
  readonly children?: JSX.Element;
}

export interface MenubarSubProps extends Renderable<PartProps, MenubarItemState> {
  /** The index in the open menu's items this parent row is. */
  readonly index: number;
  readonly class?: string;
  /** The submenu; the declared `Menubar.SubItem`s by default. */
  readonly children?: JSX.Element;
}

export interface MenubarSubContentProps extends Renderable<PartProps, void> {
  readonly class?: string;
  /** Rows of your own; without children the declared submenu items are the rows, in order. */
  readonly children?: JSX.Element;
}

export interface MenubarSubItemProps extends Renderable<PartProps, MenubarItemState> {
  /** The index in the parent row's submenu this row is. */
  readonly index: number;
  readonly class?: string;
  /** The row's content; the declared label by default. */
  readonly children?: JSX.Element;
}

/** The bar item whose menu a subtree belongs to, and the submenu row it is in, if any. */
interface MenubarMenuContextValue {
  readonly bar: number;
  readonly item: number | undefined;
}

const MenubarContext = createContext<{ readonly menubar: MenubarController }>();
const MenubarMenuContext = createContext<MenubarMenuContextValue>();

// The anchor is the decision this component makes about floating, as in Menu and Select: one box around the bar item
// and its menu, `position: relative`, and the menu is `position: absolute` in it. Nothing is measured and nothing listens
// to scroll or resize. ponytail: an inline absolute popup, so an `overflow: hidden` ancestor clips the menu and a menu
// near the viewport's edge is not flipped; a real floating layer is the wayfinder entry's "left", and neither is attempted.
const anchorClass = css.cn(css.position("relative"), css.display("inline-flex"));

const barClass = css.cn(css.display("flex"), css.alignItems("center"), css.gap(t.space._1));

const triggerClass = css.cn(
  css.padding(t.space._1, t.space._2),
  css.bg("transparent"),
  css.borderRadius(t.radius.sm),
  css.fontSize(t.font.size),
  css.color(t.color.text),
  css.cursor("pointer"),
  css.hover(css.bg(t.color.buttonBackground)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
  css.attr("aria-expanded", "true")(css.bg(t.color.buttonBackground)),
  css.attr("aria-disabled", "true")(css.color(t.color.textDisabled), css.cursor("not-allowed")),
);

// The popover surface, the same box Menu uses. No `display`: the primitive hides the menu with the `hidden` attribute, and
// a display declaration here would override the UA's `[hidden] { display: none }`.
const surfaceClass = css.cn(
  css.zIndex("var(--z-popover)"),
  css.minWidth("max-content"),
  css.padding(t.space._1),
  css.bg(t.color.overlayBackground),
  css.color(t.color.text),
  css.border("1px solid", t.color.overlayBorder),
  css.borderRadius(t.radius.lg),
  css.boxShadow(t.shadow.popover),
);

const menuClass = css.cn(
  css.position("absolute"),
  css.insetBlockStart("100%"),
  css.insetInlineStart("0"),
  css.marginBlockStart(t.space._1),
  surfaceClass,
);

// A submenu floats beside its parent row, which is the anchor: the row is `position: relative`. `inset-inline-start: 100%`
// is the row's inline end, so the popup follows the writing direction with no kit copy of it.
const submenuClass = css.cn(
  css.position("absolute"),
  css.insetBlockStart("0"),
  css.insetInlineStart("100%"),
  css.marginInlineStart(t.space._1),
  surfaceClass,
);

// The highlight is the roving tab stop the primitive announces (`tabindex="0"` on one row), not a second copy of the
// state: a pointer hover and an arrow key both move it.
const rowClass = css.cn(
  // the marker `within()` reads: the row's own `aria-expanded` is what the chevron follows
  css.group(),
  css.display("flex"),
  css.alignItems("center"),
  css.padding(t.space._1, t.space._2),
  css.borderRadius(t.radius.sm),
  css.fontSize(t.font.size),
  css.color(t.color.text),
  css.cursor("pointer"),
  css.attr("tabindex", "0")(css.bg(t.color.buttonBackground)),
  css.attr("aria-disabled", "true")(css.color(t.color.textDisabled), css.cursor("not-allowed")),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
);

const subRowClass = css.cn(
  rowClass,
  css.position("relative"),
  css.justifyContent("space-between"),
  css.gap(t.space._2),
);

// The marker is the row's own announcement: `aria-haspopup` says the row opens something and `aria-expanded` (the
// primitive's) turns it. The kit keeps no copy of the open state, as with Menu's check mark.
const chevronClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
  css.visibility("hidden"),
  css.transition("transform 120ms"),
  css.within(css.attr("aria-haspopup", "menu"))(css.visibility("visible")),
  css.within(css.attr("aria-expanded", "true"))(css.transform("rotate(90deg)")),
);

/** The submenu parts, which need a parent row; a misplaced one is a page error, not a silent no-op. */
const subOf = (
  bar: number | undefined,
  item: number | undefined,
): { readonly bar: number; readonly item: number } => {
  if (bar === undefined || item === undefined) {
    throw new Error("Menubar.SubContent and Menubar.SubItem must be inside a Menubar.Sub");
  }
  return { bar, item };
};

/**
 * APG menu and menubar, styled: a `role="menubar"` bar of top-level items, each a `Menubar.Trigger` (its bar item) with a
 * `Menubar.Content` under it, rows with one roving tab stop, and nested `Menubar.Sub` / `Menubar.SubContent` /
 * `Menubar.SubItem` levels. `createMenubar` owns the ARIA, the roving tab stop, the arrow keys with the menubar rule that
 * Right/Left moves along the bar and opens the next menu without taking focus into it, the submenu keys, Home and End,
 * Escape (one level at a time), Tab, the typeahead and the hover that opens a submenu once its menu is open. The kit adds
 * the anchor each popup floats from, the surfaces, the chevron painted from `aria-expanded`, and the DOM focus: the
 * primitive reports `focusLevel` (0 outside, 1 the bar, 2 a top-level menu, 3 a submenu) and `focusIndex`, and the kit
 * moves focus to that level only. It also listens for a pointerdown outside the bar, which the primitive does not own.
 *
 * The bar is declared on `Menubar`, once: the primitive needs the labels for typeahead, and the rows are built from the
 * same tree. Without children the bar is one `Menubar.Menu` per item, with a `Content` where the item has a menu.
 */
export const Menubar = (props: MenubarProps): JSX.Element => {
  const menubar = createMenubar({
    items: props.items,
    orientation: props.orientation,
    wrap: props.wrap,
    id: props.id,
    prefs: props.prefs,
    suppressFocusWrite: props.suppressFocusWrite,
  });
  props.onReady?.(menubar);

  let root: HTMLDivElement | undefined;

  // One move for the whole widget, as MenuContent does for one menu: the level says which container and the index which
  // row. Level 1 is the bar item itself — Right/Left opens a menu there and the focus stays on the bar — so the rule is the
  // primitive's `focusLevel`, and the kit never invents a level.
  createEffect(
    () =>
      [
        menubar.focusLevel(),
        menubar.focusIndex(),
        menubar.barStop(),
        menubar.openTop(),
        menubar.openSub(),
      ] as const,
    ([level, index, stop, top, sub]) => {
      if (root === undefined) {
        return;
      }
      const element =
        level === 1
          ? triggers(root)[stop]
          : level === 2
            ? elementWithId(root, menubar.menuProps(top).id)?.children[index]
            : level === 3
              ? elementWithId(root, menubar.submenuProps(top, sub).id)?.children[index]
              : undefined;
      if (element instanceof HTMLElement && document.activeElement !== element) {
        element.focus();
      }
    },
  );

  // A pointerdown outside the bar is the dismiss the primitive does not own: it has no document listener, and a press on a
  // bar item or a row is inside the root, so it still opens and activates.
  onSettled(() => {
    const dismiss = (event: PointerEvent): void => {
      if (root !== undefined && event.target instanceof Node && !root.contains(event.target)) {
        menubar.leave();
      }
    };
    document.addEventListener("pointerdown", dismiss);
    return () => document.removeEventListener("pointerdown", dismiss);
  });

  const merged = merge(menubar.menubarProps, () => ({
    "data-part": "menubar",
    get class() {
      return css.cn(barClass, props.class);
    },
    onKeyDown: (event: KeyboardEvent) => {
      menubar.menubarProps.onKeyDown(event);
      // typeahead is the primitive's own buffer and its key handler does not feed it, so a letter is handed over here
      if (event.key.length === 1 && event.key !== " ") {
        menubar.type(event.key);
      }
    },
  }));
  return (
    <MenubarContext value={{ menubar }}>
      {renderPart(props, merged, undefined, (part) => (
        <div
          {...part}
          ref={(element: HTMLDivElement) => {
            root = element;
          }}
        >
          {props.children ??
            menubar.items.map((item, index) => (
              <MenubarMenu index={index}>
                <MenubarTrigger />
                {item.menu.length > 0 ? <MenubarContent /> : undefined}
              </MenubarMenu>
            ))}
        </div>
      ))}
    </MenubarContext>
  );
};

const triggers = (root: HTMLElement): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="menubar-trigger"]'),
];

const elementWithId = (root: HTMLElement, id: string): HTMLElement | undefined =>
  root.querySelector<HTMLElement>(`[id="${id}"]`) ?? undefined;

/** One top-level item: the box a `Menubar.Trigger` and its `Menubar.Content` share, `position: relative`. */
export const MenubarMenu = (props: MenubarMenuProps): JSX.Element => {
  const merged = {
    "data-part": "menubar-anchor",
    get class() {
      return css.cn(anchorClass, props.class);
    },
  };
  return (
    <MenubarMenuContext value={{ bar: props.index, item: undefined }}>
      {renderPart(props, merged, undefined, (part) => (
        <div {...part}>{props.children}</div>
      ))}
    </MenubarMenuContext>
  );
};

/** The bar item: `role="menuitem"` with `aria-haspopup`, `aria-expanded` and the roving tab stop from the primitive. */
export const MenubarTrigger = (props: MenubarTriggerProps): JSX.Element => {
  const { menubar } = useContext(MenubarContext);
  const { bar } = useContext(MenubarMenuContext);
  const declared = menubar.items[bar];
  const merged = merge(menubar.barItemProps(bar), () => ({
    "data-part": "menubar-trigger",
    get class() {
      return css.cn(triggerClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <div {...part}>{props.children ?? declared?.label ?? ""}</div>
  ));
};

/**
 * The menu, floating under its bar item. Rows come from the declared tree: a row with a submenu is a `Menubar.Sub`, the rest
 * are `Menubar.Item`s. The primitive hides it and moves the focus, which `Menubar` follows by level.
 */
export const MenubarContent = (props: MenubarContentProps): JSX.Element => {
  const { menubar } = useContext(MenubarContext);
  const { bar } = useContext(MenubarMenuContext);
  const rows = menubar.items[bar]?.menu ?? [];
  const merged = merge(menubar.menuProps(bar), () => ({
    "data-part": "menubar-menu",
    get class() {
      return css.cn(menuClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <div {...part}>
      {props.children ??
        rows.map((row, index) =>
          row.submenu.length > 0 ? <MenubarSub index={index} /> : <MenubarItem index={index} />,
        )}
    </div>
  ));
};

/** One leaf row: `role="menuitem"`, its id and tab stop from the primitive, the declared label unless `children` says. */
export const MenubarItem = (props: MenubarItemProps): JSX.Element | null => {
  const { menubar } = useContext(MenubarContext);
  const { bar } = useContext(MenubarMenuContext);
  const declared = menubar.items[bar]?.menu[props.index];
  if (declared === undefined) {
    return null;
  }
  const merged = merge(menubar.menuItemProps(bar, props.index), () => ({
    "data-part": "menubar-item",
    get class() {
      return css.cn(rowClass, props.class);
    },
  }));
  const state: MenubarItemState = {
    highlighted: () =>
      menubar.focusLevel() === 2 &&
      menubar.openTop() === bar &&
      menubar.focusIndex() === props.index,
    disabled: () => declared.disabled,
  };
  return renderPart(props, merged, state, (part) => (
    <div {...part}>{props.children ?? declared.label}</div>
  ));
};

/**
 * A parent row and its submenu: the row is the anchor (`position: relative`) and the `Menubar.SubContent` sits in it, so the
 * popup floats beside the row and the row's announcement is what the chevron follows. `children` replaces the submenu.
 */
export const MenubarSub = (props: MenubarSubProps): JSX.Element | null => {
  const { menubar } = useContext(MenubarContext);
  const { bar } = useContext(MenubarMenuContext);
  const declared = menubar.items[bar]?.menu[props.index];
  if (declared === undefined) {
    return null;
  }
  const merged = merge(menubar.menuItemProps(bar, props.index), () => ({
    "data-part": "menubar-sub",
    get class() {
      return css.cn(subRowClass, props.class);
    },
  }));
  const state: MenubarItemState = {
    highlighted: () =>
      menubar.focusLevel() === 2 &&
      menubar.openTop() === bar &&
      menubar.focusIndex() === props.index,
    disabled: () => declared.disabled,
  };
  return (
    <MenubarMenuContext value={{ bar, item: props.index }}>
      {renderPart(props, merged, state, (part) => (
        <div {...part}>
          <span>{declared.label}</span>
          <span aria-hidden="true" class={chevronClass}>
            ›
          </span>
          {props.children ?? <MenubarSubContent />}
        </div>
      ))}
    </MenubarMenuContext>
  );
};

/** The submenu: `role="menu"` and `hidden` from the primitive, absolute in the parent row. */
export const MenubarSubContent = (props: MenubarSubContentProps): JSX.Element => {
  const { menubar } = useContext(MenubarContext);
  const context = useContext(MenubarMenuContext);
  const { bar, item } = subOf(context.bar, context.item);
  const rows = menubar.items[bar]?.menu[item]?.submenu ?? [];
  const merged = merge(menubar.submenuProps(bar, item), () => ({
    "data-part": "menubar-submenu",
    get class() {
      return css.cn(submenuClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <div {...part}>
      {props.children ?? rows.map((_, index) => <MenubarSubItem index={index} />)}
    </div>
  ));
};

/** One row of a submenu: `role="menuitem"` and its tab stop from the primitive, the declared label unless `children` says. */
export const MenubarSubItem = (props: MenubarSubItemProps): JSX.Element | null => {
  const { menubar } = useContext(MenubarContext);
  const context = useContext(MenubarMenuContext);
  const { bar, item } = subOf(context.bar, context.item);
  const declared = menubar.items[bar]?.menu[item]?.submenu[props.index];
  if (declared === undefined) {
    return null;
  }
  const merged = merge(menubar.submenuItemProps(bar, item, props.index), () => ({
    "data-part": "menubar-subitem",
    get class() {
      return css.cn(rowClass, props.class);
    },
  }));
  const state: MenubarItemState = {
    highlighted: () =>
      menubar.focusLevel() === 3 &&
      menubar.openTop() === bar &&
      menubar.openSub() === item &&
      menubar.focusIndex() === props.index,
    disabled: () => declared.disabled,
  };
  return renderPart(props, merged, state, (part) => (
    <div {...part}>{props.children ?? declared.label}</div>
  ));
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 });
check.contrast(t.color.muted, t.color.page, { min: 4.5 });
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 });

export { t };

import { type Menubar as MenubarController } from "@cssints/headless";
import type { Json } from "@cssints/apg-specs/scenario";
import type { MenuMenubarConfig } from "@cssints/apg-specs/apg/menu-menubar.bridge";
import type { Mounted } from "./menubar-driver.ts";
import { Menubar, MenubarContent, MenubarMenu, MenubarTrigger } from "./menubar.tsx";
import { render } from "@solidjs/web";

const asRecord = (value: Json | undefined): Record<string, Json> => {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new Error(`expected an object, got ${JSON.stringify(value)}`);
  }
  return value as Record<string, Json>;
};

/**
 * Renders the kit's menubar with the `menu-menubar.qnt` fixed tree: the first bar item's menu has three items with a
 * submenu on the second, the second bar item has a menu of two, the third none.
 */
export const mountMenubar = (config: MenuMenubarConfig): Mounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const events = new Map<string, Json[]>();
  let api: MenubarController | undefined;

  const labels = config.items;
  const tree = [
    {
      label: labels[0] ?? "File",
      menu: [
        { label: "New" },
        { label: "More", submenu: [{ label: "One" }, { label: "Two" }] },
        { label: "Close" },
      ],
    },
    {
      label: labels[1] ?? "Edit",
      menu: [{ label: "Undo" }, { label: "Redo" }],
    },
    { label: labels[2] ?? "About" },
  ];

  const dispose = render(
    () => (
      <Menubar
        items={tree}
        orientation={config.orientation}
        onReady={(menubar) => {
          api = menubar;
        }}
      >
        <MenubarMenu index={0}>
          <MenubarTrigger />
          <MenubarContent />
        </MenubarMenu>
        <MenubarMenu index={1}>
          <MenubarTrigger />
          <MenubarContent />
        </MenubarMenu>
        <MenubarMenu index={2}>
          <MenubarTrigger />
        </MenubarMenu>
      </Menubar>
    ),
    root,
  );

  return {
    root,
    events,
    setProp: (name, value) => {
      switch (name) {
        case "focus":
          api?.focusIn();
          break;
        case "leave":
        case "blur":
          api?.leave();
          break;
        case "key": {
          const record = asRecord(value);
          if (typeof record["key"] !== "string") {
            throw new Error(`key needs a string, got ${JSON.stringify(value)}`);
          }
          api?.keyDown(record["key"]);
          break;
        }
        case "typeahead":
          api?.typeaheadCode(Number(value));
          break;
        case "type":
          api?.type(String(value));
          break;
        default:
          throw new Error(`fixture has no prop ${name}`);
      }
    },
    focus: () => {
      const level = api?.focusLevel();
      if (level === 1) {
        return `menuitem:${api?.barStop()}`;
      }
      if (level === 2) {
        return `menuitem:${api?.openTop()}/${api?.focusIndex()}`;
      }
      if (level === 3) {
        return `menuitem:${api?.openTop()}/${api?.openSub()}/${api?.focusIndex()}`;
      }
      return null;
    },
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

/** The bar the kit's own DOM assertions drive: one menu with a submenu, one without, and a bar item that has no menu. */
export const mountBar = (): { readonly root: HTMLElement; readonly dispose: () => void } => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(
    () => (
      <Menubar
        items={[
          {
            label: "File",
            menu: [
              { label: "New" },
              { label: "Export", submenu: [{ label: "PDF" }, { label: "PNG" }] },
              { label: "Close" },
            ],
          },
          { label: "Edit", menu: [{ label: "Undo" }, { label: "Redo" }] },
          { label: "Help" },
        ]}
      />
    ),
    root,
  );
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { type ActionStep, type Driver, type Json, Unsupported } from "@cssints/apg-specs/scenario";
import { userEvent } from "vite-plus/test/browser";

/**
 * The DOM side of the menubar bridge. Unlike the generic `domDriver`, a target is the spec's own label
 * (`menuitem:0`, `menuitem:0/1/0`, `menu:0`, `submenu:1`), because the bar nests its parts; this maps each label onto the
 * kit's `data-part` names. `Mounted` is the contract a fixture returns.
 */
export interface Mounted {
  readonly root: HTMLElement;
  /** Apply a scenario `prop` step (programmatic input) to the mounted widget. */
  readonly setProp: (name: string, value: Json | undefined) => void;
  /** Callback payloads, recorded under their canonical name. */
  readonly events: ReadonlyMap<string, ReadonlyArray<Json>>;
  readonly value?: () => Json;
  /** The part the primitive itself considers focused (`menuitem:0`), or `null`. */
  readonly focus?: () => string | null;
  readonly dispose: () => void;
}

const BOOLEAN_ATTRS = new Set(["hidden", "disabled"]);

const settle = (): Promise<void> =>
  new Promise((resolve) => {
    requestAnimationFrame(() => {
      setTimeout(resolve, 0);
    });
  });

const NAMED_KEYS = new Set([
  "Enter",
  "Tab",
  "Escape",
  "Backspace",
  "Delete",
  "Home",
  "End",
  "PageUp",
  "PageDown",
]);

const keyToken = (key: string): string => {
  if (key === " " || key === "Space") {
    return " ";
  }
  return NAMED_KEYS.has(key) || /^F\d+$/.test(key) || key.startsWith("Arrow") ? `{${key}}` : key;
};

const keyboardSyntax = (key: string): string => {
  if (!key.includes("+")) {
    return keyToken(key);
  }
  const parts = key.split("+");
  const main = parts.pop() ?? "";
  return `${parts.map((modifier) => `{${modifier}>}`).join("")}${keyToken(main)}${parts
    .map((modifier) => `/{${modifier}}`)
    .join("")}`;
};

const partsOf = (root: HTMLElement, name: string): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>(`[data-part="${name}"]`),
];

const childrenOf = (element: HTMLElement): HTMLElement[] =>
  [...element.children].filter((child): child is HTMLElement => child instanceof HTMLElement);

const submenuOf = (row: HTMLElement | undefined): HTMLElement | undefined =>
  row?.querySelector<HTMLElement>('[data-part="menubar-submenu"]') ?? undefined;

const at = <T>(list: readonly T[], index: number): T | undefined => list[index];

/** The spec's target labels, mapped onto the kit's parts: the triggers, each menu, then each submenu. */
const elementOf = (root: HTMLElement, target: string): HTMLElement => {
  const missing = (): never => {
    throw new Unsupported(`part ${target}`);
  };
  if (target === "menubar") {
    return at(partsOf(root, "menubar"), 0) ?? missing();
  }
  if (target.startsWith("menu:")) {
    return at(partsOf(root, "menubar-menu"), Number(target.slice("menu:".length))) ?? missing();
  }
  if (target.startsWith("submenu:")) {
    const index = Number(target.slice("submenu:".length));
    const menus = partsOf(root, "menubar-menu");
    const rows = menus.flatMap((menu) => childrenOf(menu));
    const submenus = rows.flatMap((row) => submenuOf(row) ?? []);
    return at(submenus, index - 1) ?? missing();
  }
  if (!target.startsWith("menuitem:")) {
    return missing();
  }
  const path = target
    .slice("menuitem:".length)
    .split("/")
    .map((part) => Number(part));
  const [bar, item, sub] = path;
  if (bar === undefined || !Number.isInteger(bar)) {
    return missing();
  }
  if (item === undefined) {
    return at(partsOf(root, "menubar-trigger"), bar) ?? missing();
  }
  const row = at(childrenOf(at(partsOf(root, "menubar-menu"), bar) ?? missing()), item);
  if (sub === undefined) {
    return row ?? missing();
  }
  return at(childrenOf(submenuOf(row) ?? missing()), sub) ?? missing();
};

export const menubarDriver = (mounted: Mounted): Driver => {
  const { root } = mounted;

  const activePart = (): string | null => {
    const active = document.activeElement;
    if (!(active instanceof HTMLElement) || !root.contains(active)) {
      return null;
    }
    return active.dataset["part"] ?? null;
  };

  return {
    perform: async (step: ActionStep) => {
      switch (step.event) {
        case "focus":
          if (step.target === undefined || step.target === "menubar") {
            mounted.setProp("focus", undefined);
          } else {
            elementOf(root, step.target).focus();
          }
          break;
        case "blur": {
          const active = document.activeElement;
          if (active instanceof HTMLElement && root.contains(active)) {
            active.blur();
          } else if (step.target !== undefined) {
            elementOf(root, step.target).blur();
          }
          break;
        }
        case "click":
          // dispatch without native pointer focus: the widget owns roving focus
          elementOf(root, step.target ?? "").dispatchEvent(
            new MouseEvent("click", { bubbles: true, cancelable: true }),
          );
          break;
        case "hover":
          await userEvent.hover(elementOf(root, step.target ?? ""));
          break;
        case "unhover":
          await userEvent.unhover(elementOf(root, step.target ?? ""));
          break;
        case "key": {
          // dispatch to whatever currently holds focus inside the widget, exactly like a user
          const active = document.activeElement;
          if (active instanceof HTMLElement && root.contains(active)) {
            await userEvent.keyboard(keyboardSyntax(step.key ?? ""));
          }
          break;
        }
        case "prop":
          mounted.setProp(step.prop ?? "", step.value);
          break;
        default:
          throw new Unsupported(`event ${step.event}`);
      }
      await settle();
    },
    observer: {
      focus: () => (mounted.focus === undefined ? activePart() : mounted.focus()),
      attr: (target, name) => {
        if (name.startsWith("data-")) {
          throw new Unsupported(`styling hook ${name}`);
        }
        const value = elementOf(root, target).getAttribute(name);
        if (value === null) {
          return null;
        }
        if (value === "" && BOOLEAN_ATTRS.has(name)) {
          return "true";
        }
        return value;
      },
      visible: () => [
        ...partsOf(root, "menubar-menu").flatMap((menu, bar) =>
          menu.checkVisibility() ? [`menu:${bar}`] : [],
        ),
        ...partsOf(root, "menubar-submenu").flatMap((submenu, index) =>
          submenu.checkVisibility() ? [`submenu:${index + 1}`] : [],
        ),
      ],
      events: (name) => mounted.events.get(name) ?? [],
      ...(mounted.value === undefined ? {} : { value: mounted.value }),
    },
    dispose: mounted.dispose,
  };
};

